        this.age = age;
        this.grades = new double[5]; // Assuming a maximum of 5 grades
        this.numberOfGrades = 0;
    }

    public void addGrade(double grade) {
        if (numberOfGrades < grades.length) {
            grades[numberOfGrades++] = grade;
        }
