 Here's a Python program that calculates the mean, median, and mode of a given set of data:

```python
def mean(numbers):
    return sum(numbers) / len(numbers)

def median(numbers):
    sorted_numbers = sorted(numbers)
    length = len(sorted_numbers)
    if length == 0:
        return None
    elif length % 2 == 0:
        return (sorted_numbers[length // 2 - 1] + sorted_numbers[length // 2]) / 2
    else:
        return sorted_numbers[length // 2]

def mode(numbers):
    from collections import Counter
    counter = Counter(numbers)
    max_count = max(counter.values())
    return [num for num, freq in counter.items() if freq == max_count]

def main():
    data = [1, 2, 3, 4, 4, 4, 5, 6, 6, 7, 7, 8, 8, 8, 9, 9, 9]
    print("Mean:", mean(data))
    print("Median:", median(data))
    print("Mode:", mode(data))

if __name__ == "__main__":
    main()
```

You can replace the `data` list with your own set of numbers to calculate the mean, median, and mode for that data. The program uses the built-in `sum()` function to calculate the mean, sorts the list using the built-in `sorted()` function to find the median, and uses the `collections.Counter` class to find the mode.

