    } else {
      this.tail.next = newNode;
      newNode.prev = this.tail;
      this.tail = newNode;
    }
    this.length++;
  }

  // Insert a new node with given data at the specified position
  insertAt(data, position) {
    const newNode = new Node(data);
    if (position < 0 || position > this.length) {
      throw new Error("Invalid position");
    }

    let current = this.head;
    let index = 0;

    if (position === 0) {
      newNode.next = current;
      if (current) current.prev = newNode;
      this.head = newNode;
    } else {
      while (index++ < position - 1) {
        current = current.next;
      }
      newNode.next = current.next;
      newNode.prev = current;
      if (newNode.next) newNode.next.prev = newNode;
      current.next = newNode;
    }
    this.length++;
  }

  // Remove a node at the specified position
  removeAt(position) {
    if (position < 0 || position >= this.length) {
      throw new Error("Invalid position");
    }

    let current = this.head;
    let index = 0;

    if (position === 0) {
      this.head = current.next;
      if (this.head) this.head.prev = null;
    } else {
      while (index++ < position) {
        current = current.next;
      }
      current.prev.next = current.next;
      if (current.next) current.next.prev = current.prev;
    }
    this.length--;
    return current.data;
  }

  // Print the elements of the list
  printList() {
    let current = this.head;
    let list = [];
    while (current) {
      list.push(current.data);
      current = current.next;
    }
    return list;
  }
}

// Usage example:
const myList = new LinkedList();
myList.append(1);
myList.append(2);
myList.append(3);
myList.insertAt(0, 0);
myList.insertAt(4, 4);
console.log(myList.printList()); // [0, 1, 2, 3, 4]
myList.removeAt(2);
console.log(myList.printList()); // [0, 1, 4]
```

This implementation includes methods for appending, inserting, removing, and printing the elements of the double-linked list. The Node class represents each node in the list, while the LinkedList class manages the list as a whole.

