 Here's a simple Objective-C program that checks if two strings are anagrams. An anagram is a word or phrase formed by rearranging the letters of a different word or phrase, using all the original letters exactly once.

```objective-c
#import <Foundation/Foundation.h>

NSString *checkAnagrams(NSString *str1, NSString *str2) {
    NSMutableCharacterSet *charSet = [NSMutableCharacterSet characterSetWithCharactersInString:str1];
    [charSet formUnion:[NSMutableCharacterSet characterSetWithCharactersInString:str2]];

    if (charSet.count != str1.length + str2.length) {
        return @"Not Anagrams";
    }

    NSMutableDictionary *letterCount = [NSMutableDictionary dictionary];
    for (NSInteger i = 0; i < [str1 length]; i++) {
        if (![letterCount objectForKey:[str1 substringWithRange:NSMakeRange(i, 1)]]) {
            [letterCount setObject:@1 forKey:[str1 substringWithRange:NSMakeRange(i, 1)]];
        } else {
            NSNumber *count = [letterCount objectForKey:[str1 substringWithRange:NSMakeRange(i, 1)]];
            [letterCount setObject:[NSNumber numberWithInteger:[count integerValue] + 1] forKey:[str1 substringWithRange:NSMakeRange(i, 1)]];
        }
    }

    for (NSInteger i = 0; i < [str2 length]; i++) {
        if (![letterCount objectForKey:[str2 substringWithRange:NSMakeRange(i, 1)]]) {
            return @"Not Anagrams";
        }

        NSNumber *count = [letterCount objectForKey:[str2 substringWithRange:NSMakeRange(i, 1)]];
        if ([count integerValue] == 0) {
            return @"Not Anagrams";
        }
