 A linked list is a linear data structure, in which the elements are linked using pointers. Each element, called a node, consists of data and a reference (pointer) to the next node in the sequence. Here's a basic design for a singly linked list in C++:

```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* next;

    Node(int data) : data(data), next(nullptr) {}
};

class SinglyLinkedList {
private:
    Node* head;

public:
    SinglyLinkedList() : head(nullptr) {}

    ~SinglyLinkedList() {
        while (head != nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insertAtBeginning(int data) {
        Node* newNode = new Node(data);
        newNode->next = head;
        head = newNode;
    }

    void insertAtEnd(int data) {
        Node* newNode = new Node(data);

        if (head == nullptr) {
            head = newNode;
            return;
        }

        Node* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }
        current->next = newNode;
    }

    void display() {
        Node* current = head;
        while (current != nullptr) {
            std::cout << current->data << " -> ";
            current = current->next;
        }
        std::cout << "NULL" << std::endl;
    }
};

int main() {
    SinglyLinkedList list;
    list.insertAtBeginning(1);
    list.insertAtBeginning(2);
    list.insertAtEnd(3);
    list.insertAtEnd(4);
    list.display();

    return 0;
}
```

This code defines a `Node` class that represents each node in the linked list, and a `SinglyLinkedList` class that manages the list. The `SinglyLinkedList` class has methods to insert nodes at the beginning and end of the list, display the list, and delete all nodes when the list is destroyed. The `main` function demonstrates how to use the `SinglyLinkedList` class.

