 Here is a simple Python class definition for a complex number:

```python
class Complex:
    def __init__(self, real=0, imaginary=0):
        self.real = real
        self.imaginary = imaginary

    def __str__(self):
        if self.imaginary >= 0:
            return f"{self.real}+{self.imaginary}j"
        else:
            return f"{self.real}{self.imaginary}j"

    def __add__(self, other):
        if isinstance(other, Complex):
            return Complex(self.real + other.real, self.imaginary + other.imaginary)
        elif isinstance(other, (int, float)):
            return Complex(self.real + other, self.imaginary)
        else:
            raise TypeError("Unsupported operand type(s) for +: 'Complex' and '{}'".format(type(other).__name__))

    def __sub__(self, other):
        if isinstance(other, Complex):
            return Complex(self.real - other.real, self.imaginary - other.imaginary)
        elif isinstance(other, (int, float)):
            return Complex(self.real - other, self.imaginary)
        else:
            raise TypeError("Unsupported operand type(s) for -: 'Complex' and '{}'".format(type(other).__name__))

    def __mul__(self, other):
        if isinstance(other, Complex):
            return Complex(
                self.real * other.real - self.imaginary * other.imaginary,
                self.real * other.imaginary + self.imaginary * other.real
            )
        elif isinstance(other, (int, float)):
            return Complex(self.real * other, self.imaginary * other)
        else:
            raise TypeError("Unsupported operand type(s) for *: 'Complex' and '{}'".format(type(other).__name__))

    def __truediv__(self, other):
        if isinstance(other, Complex):
            conjugate_other = Complex(other.real, -other.imaginary)
            return Complex(
                (self.real * conjugate_other.real + self.imaginary * conjugate_other.imaginary) / (other.real ** 2 + other.imaginary ** 2),
                (self.imaginary * conjugate_other.real - self.real * conjugate_other.imaginary) / (other.real ** 2 + other.imaginary ** 2)
            )
        elif isinstance(other, (int, float)):
            return Complex(self.real / other, self.imaginary / other)
        else:
            raise TypeError("Unsupported operand type(s) for /: 'Complex' and '{}'".format(type(other).__name__))
```

With this class, you can create complex numbers, perform arithmetic operations, and convert them to strings:

```python
